def _warn_if_value_exceeds_max_storage_bytes(value: JsonValue) -> None:
    """
    Emit a warning when the JSON-serialized ``value`` exceeds the configured size limit.

    The limit is ``[state_store] max_value_storage_bytes``; a value of ``0`` disables the
    check. This only warns — the caller still proceeds to send the value. The API server
    enforces the limit authoritatively (rejecting oversized writes with HTTP 422).
    """
    import json

    max_bytes = conf.getint("state_store", "max_value_storage_bytes", fallback=65535)
    if max_bytes <= 0:
        return
    size = len(json.dumps(value).encode("utf-8"))
    if size > max_bytes:
        log.warning(
            "State store value is %d bytes, which exceeds the configured "
            "[state_store] max_value_storage_bytes limit of %d bytes. The value will still be "
            "written, but consider storing large payloads elsewhere.",
            size,
            max_bytes,
